import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"画像モデル配備","description":"本機に A1111 または ComfyUI を配備し、MiniTavern から LAN で生図；クラウド画像 API がないときのローカル Stable Diffusion。","frontmatter":{"title":"画像モデル配備","description":"本機に A1111 または ComfyUI を配備し、MiniTavern から LAN で生図；クラウド画像 API がないときのローカル Stable Diffusion。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"画像モデル配備 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"本機に A1111 または ComfyUI を配備し、MiniTavern から LAN で生図；クラウド画像 API がないときのローカル Stable Diffusion。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/local/image-gen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/local/image-gen"}]]},"headers":[],"relativePath":"ja/local/image-gen/index.md","filePath":"ja/local/image-gen/index.md","lastUpdated":1787224147000}'),i={name:"ja/local/image-gen/index.md"};function n(d,t,l,s,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="画像モデル配備" tabindex="-1">画像モデル配備 <a class="header-anchor" href="#画像モデル配備" aria-label="Permalink to &quot;画像モデル配備&quot;">​</a></h1><p>MiniTavern はクラウド画像（OpenAI／Gemini／OpenRouter／Qwen）と<strong>本機</strong> Stable Diffusion 系サービスに対応：</p><table tabindex="0"><thead><tr><th>本機バックエンド</th><th>App プラットフォーム</th><th>デフォルトポート</th></tr></thead><tbody><tr><td><a href="./a1111">AUTOMATIC1111／SD WebUI</a></td><td>A1111(SD WebUI)</td><td><code>7860</code></td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>ComfyUI</td><td><code>8188</code>（Desktop はよく <code>8000</code>）</td></tr></tbody></table><p>スマホの MiniTavern は<strong>端末内で拡散モデルを走らせない</strong>；図は PC（またはクラウド GPU）で生成し、App はリクエストと結果表示のみ。</p><h2 id="必要なもの" tabindex="-1">必要なもの <a class="header-anchor" href="#必要なもの" aria-label="Permalink to &quot;必要なもの&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>推奨</th></tr></thead><tbody><tr><td>PC</td><td>Windows が手軽；macOS／Linux も可</td></tr><tr><td>GPU</td><td><strong>NVIDIA 6GB+</strong> が快適（SD 1.5）；SDXL／大きめモデルは <strong>8–12GB+</strong> 推奨</td></tr><tr><td>独显なし</td><td>CPU（非常に遅い）またはクラウド GPU レンタル（時間課金、無料ではない）</td></tr><tr><td>ネットワーク</td><td>スマホと PC を同一 Wi‑Fi（ゲスト隔離ネットは不可）</td></tr><tr><td>ディスク</td><td>モデルはしばしば <strong>2–10GB+</strong>／個、余裕を確保</td></tr></tbody></table><p>GPU がなく配備もしたくない：<a href="/ultra_guides/ja/free-cloud/#無料の画像生成">無料クラウド · 画像生成</a> のクラウド無料画像帯（あれば）、または当面チャットのみ。</p><h2 id="どちらの経路か" tabindex="-1">どちらの経路か <a class="header-anchor" href="#どちらの経路か" aria-label="Permalink to &quot;どちらの経路か&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ツール</th><th>向いている人</th><th>難度</th></tr></thead><tbody><tr><td><a href="./a1111">A1111</a></td><td>従来 WebUI、パラメータが直感、酒場生態でよくつなぐ</td><td>中</td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>ワークフロー／新モデル対応が速い；App は内蔵デフォルト workflow</td><td>中</td></tr></tbody></table><p>どちらも最後は：<a href="./connect-app">MiniTavern で画像接続を設定</a>。</p><h2 id="推奨読書順" tabindex="-1">推奨読書順 <a class="header-anchor" href="#推奨読書順" aria-label="Permalink to &quot;推奨読書順&quot;">​</a></h2><ol><li>ハードウェアに合わせて <a href="./a1111">A1111</a> または <a href="./comfyui">ComfyUI</a> でインストールとモデル取得</li><li><strong>API＋LAN リスン</strong>を有効化（各チュートリアル内）</li><li><a href="./connect-app">MiniTavern 接続</a> して測連</li><li>チャットで <code>/imagine</code> または添付 → 生図（<a href="/ultra_guides/ja/manual/model-link#画像生成接続--返信画像--キーワード">モデル接続 · 画像生成</a>）</li><li><a href="/ultra_guides/ja/local/">ローカルモデル</a> 総覧へ戻る</li></ol><h2 id="重要な注意" tabindex="-1">重要な注意 <a class="header-anchor" href="#重要な注意" aria-label="Permalink to &quot;重要な注意&quot;">​</a></h2><ul><li>スマホに入れるアドレスは PC の <strong>LAN IP</strong>（例 <code>192.168.1.8</code>）、<strong><code>localhost</code>／<code>127.0.0.1</code> は不可</strong>。</li><li>A1111 は <strong><code>--api</code></strong> 必須；Web UI だけでは不足。</li><li>ComfyUI は <strong><code>--listen</code></strong>（または Desktop で Listen を <code>0.0.0.0</code>）が必要で、スマホから到達できること。</li><li>ファイアウォールでポート開放；認証なしの生図 API を公網に晒さない。</li><li>現行 App の Comfy デフォルト workflow は<strong>参考図を消費しない</strong>；顔固定が必要なら A1111 または参考図対応のクラウドを優先。</li></ul>',14)])])}const g=e(i,[["render",n]]);export{p as __pageData,g as default};
